{"script":"() => {
  const text = document.body.innerText;
  const matches = [];

  // Find sections about iPhone pricing and release
  const sections = [
    'Pre-order starting',
    'Available starting',
    'Buy from',
    'Lease from',
    'iPhone 18 Pro',
    'iPhone Duo'
  ];

  sections.forEach(term => {
    const idx = text.indexOf(term);
    if (idx !== -1) {
      matches.push({ term, context: text.substring(Math.max(0, idx-50), idx+200) });
    }
  });

  return matches;
}"}

